frappe.ui.form.on('Attendance', {
    onload: function(frm) {
        // Check if the user is not an Administrator
        if (frappe.session.user !== 'Administrator') {
            // Make an API call to get the Employee linked with the current user
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Employee',
                    filters: { user_id: frappe.session.user },
                    fieldname: 'name'
                },
                callback: function(r) {
                    if (r.message) {
                        // If Employee record found, set it in the Employee field
                        frm.set_value('employee', r.message.name);
                        // Fetch and set the default shift for the employee
                        fetch_default_shift(frm, r.message.name);
                    }
                }
            });
        }
    },

    refresh: function(frm) {
        // Set the 'status' field options to include an empty option and 'Present'
        frm.set_df_property('status', 'options', '\nPresent');
        // Refresh the field to reflect the changes
        frm.refresh_field('status');
    },

    employee: function(frm) {
        // Fetch default shift whenever employee is changed manually or automatically
        if (frm.doc.employee) {
            fetch_default_shift(frm, frm.doc.employee);
        }
    }
});

// Function to fetch the default shift for the employee and set it in the shift field
function fetch_default_shift(frm, employee) {
    frappe.call({
        method: "frappe.client.get_value",
        args: {
            doctype: "Employee",
            fieldname: "default_shift",
            filters: { name: employee }
        },
        callback: function(r) {
            if (r.message) {
                frm.set_value("shift", r.message.default_shift || "");
                console.log("Shift:", r.message.default_shift); // Log the shift to the console
            } else {
                frm.set_value("shift", "");
                console.log("Shift not found for employee:", employee); // Log if shift is not found
            }
        }
    });
}

