// Function to create Address linked to the Customer
function create_address(customer_name, values, address_type, address_line, city, state, country, pincode) {
    let address_doc = {
        doctype: 'Address',
        address_title: customer_name + ' ' + address_type,
        address_type: address_type,
        address_line1: address_line,
        city: city,
        state: state,
        country: country,
        pincode: pincode,
        links: [{ link_doctype: 'Customer', link_name: customer_name }]
    };

    frappe.call({
        method: 'frappe.client.insert',
        args: { doc: address_doc },
        callback: function (res) {
            if (res.message) {
                frappe.msgprint(__('{} Address Created for Customer: {}', [address_type, customer_name]));
            }
        }
    });
}

