            if (frm.doc.custom_lead_type === 'Roasted coffee lead') {
                $('a.dropdown-item:contains("Supplier Quotation")').hide();
                $('a.dropdown-item:contains("Request For Quotation")').hide();
                $('a.dropdown-item:contains("Customer")').hide();
                $('a.dropdown-item:contains("Quotation")').hide();

                frappe.show_alert("Create options are disabled for Roasted Coffee Leads ☕", 5);
            } else {
                $('a.dropdown-item:contains("Supplier Quotation")').hide();
                $('a.dropdown-item:contains("Request For Quotation")').hide();
                $('a.dropdown-item:contains("Customer")').hide();
            }

            // 🧽 Remove the top-left "Open" status badge
            $('.indicator-pill').remove();

        }, 300); // Wait for DOM to fully render

        // Optional: Hide status field too, if needed
        frm.set_df_property('status', 'hidden', 1);
    }
});

frappe.ui.form.on('Quotation', {
    before_submit: function(frm) {
        frappe.call({
            method: "frappe.client.get_attachments",
            args: {
                doctype: frm.doctype,
                name: frm.docname
            },
            callback: function(r) {
                const attachments = r.message || [];

                if (attachments.length === 0) {
                    frappe.throw("📎 Please attach at least one file before submitting the Quotation.");
                }
            },
            async: false  // make sure the check completes before submission
        });
    }
});

frappe.ui.form.on('Stock Entry Detail', {
  custom_loss(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    // Only apply if custom_loss is a number and greater than 0
    if (row.custom_loss > 0 && row.qty) {
      const loss = parseFloat(row.custom_loss) || 0;
      const original_qty = parseFloat(row.qty) || 0;

      // Store original qty as "before loss" if not already stored
      if (!row.custom_qty_before_loss || row.custom_qty_before_loss === 0) {
        frappe.model.set_value(cdt, cdn, 'custom_qty_before_loss', original_qty);
      }

      const final_qty = Math.round(original_qty * (1 - (loss / 100)) * 10000) / 10000;

      frappe.model.set_value(cdt, cdn, 'qty', final_qty);
      frappe.model.set_value(cdt, cdn, 'transfer_qty', final_qty);
    }
  }
});
